1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <meta name="color-scheme" content="light dark">
7	  <title>Animated Circle - Interactive Demo</title>
8	  <meta name="description" content="A responsive, accessible circle that changes color when clicked">
9	  <meta name="theme-color" content="#ffffff" media="(prefers-color-scheme: light)">
10	  <meta name="theme-color" content="#111111" media="(prefers-color-scheme: dark)">
11	  <link rel="icon" href="data:,">
12	  <style>
13	    *,
14	    *::before,
15	    *::after {
16	      box-sizing: border-box;
17	      margin: 0;
18	      padding: 0;
19	    }
20	    :root {
21	      color-scheme: light dark;
22	      --bg: #fff;
23	      --text: #374151;
24	      --fg: #2563eb;
25	      --shadow: rgba(0, 0, 0, 0.1);
26	      --kbd-bg: rgba(0, 0, 0, 0.1);
27	      --drop: drop-shadow(0 4px 12px var(--shadow));
28	    }
29	    [data-color="red"] { --fg: #dc2626; }
30	    [data-color="green"] { --fg: #16a34a; }
31	    [data-color="amber"] { --fg: #d97706; }
32	    [data-color="violet"] { --fg: #7c3aed; }
33	    [data-color="cyan"] { --fg: #0891b2; }
34	    @media (prefers-color-scheme: dark) {
35	      :root {
36	        --bg: #111;
37	        --text: #d1d5db;
38	        --fg: #93c5fd;
39	        --shadow: rgba(0, 0, 0, 0.6);
40	        --kbd-bg: rgba(255, 255, 255, 0.15);
41	      }
42	      [data-color="red"] { --fg: #fca5a5; }
43	      [data-color="green"] { --fg: #86efac; }
44	      [data-color="amber"] { --fg: #fcd34d; }
45	      [data-color="violet"] { --fg: #c4b5fd; }
46	      [data-color="cyan"] { --fg: #67e8f9; }
47	    }
48	    @media (prefers-contrast: more) {
49	      :root {
50	        --shadow: rgba(0, 0, 0, 0.9);
51	        --drop: drop-shadow(0 2px 8px var(--shadow));
52	      }
53	      .hint {
54	        opacity: 1 !important;
55	      }
56	    }
57	    @media (forced-colors: active) {
58	      svg circle {
59	        stroke: CanvasText;
60	        stroke-width: 2;
61	      }
62	    }
63	    body {
64	      min-height: 100vh;
65	      min-height: 100dvh;
66	      display: grid;
67	      place-items: center;
68	      padding: 1rem;
69	      background: var(--bg);
70	      color: var(--text);
71	      font-family: system-ui, -apple-system, sans-serif;
72	    }
73	    main {
74	      width: 100%;
75	      display: flex;
76	      flex-direction: column;
77	      align-items: center;
78	      text-align: center;
79	    }
80	    button {
81	      display: block;
82	      width: min(360px, 100%, 60vh);
83	      aspect-ratio: 1;
84	      border: 0;
85	      border-radius: 50%;
86	      background: none;
87	      color: var(--fg);
88	      cursor: pointer;
89	      touch-action: manipulation;
90	      -webkit-tap-highlight-color: transparent;
91	      transition: color 0.4s ease;
92	      position: relative;
93	      min-height: 48px;
94	      min-width: 48px;
95	    }
96	    .color-indicator {
97	      position: absolute;
98	      bottom: 12%;
99	      right: 12%;
100	      width: 1rem;
101	      height: 1rem;
102	      border-radius: 50%;
103	      background: currentColor;
104	      border: 2px solid var(--bg);
105	      box-shadow: 0 2px 4px var(--shadow);
106	    }
107	    .no-transition,
108	    .no-transition svg,
109	    .no-transition .color-indicator {
110	      transition: none !important;
111	    }
112	    button:focus-visible {
113	      outline: 3px solid currentColor;
114	      /* Must clear the scaled-up circle (up to 9px) or the ring merges with it */
115	      outline-offset: 12px;
116	    }
117	    svg {
118	      display: block;
119	      width: 100%;
120	      height: 100%;
121	      overflow: visible;
122	      opacity: 0.85;
123	      filter: var(--drop);
124	      transition: opacity 0.3s ease;
125	      backface-visibility: hidden;
126	      will-change: opacity, transform;
127	    }
128	    button:active svg,
129	    button:focus-visible svg {
130	      opacity: 1;
131	    }
132	    @keyframes pulse {
133	      0% {
134	        filter: var(--drop) drop-shadow(0 0 16px currentColor);
135	      }
136	      100% {
137	        filter: var(--drop) drop-shadow(0 0 0 transparent);
138	      }
139	    }
140	    @media (hover: hover) {
141	      button:hover svg {
142	        opacity: 1;
143	      }
144	    }
145	    @media (prefers-reduced-motion: no-preference) {
146	      svg {
147	        transition:
148	          transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1),
149	          opacity 0.3s ease;
150	      }
151	      button:focus-visible svg {
152	        transform: scale(1.05);
153	      }
154	      button:active svg {
155	        transform: scale(0.97);
156	      }
157	      button.color-changed svg {
158	        animation: pulse 0.5s ease-out;
159	      }
160	    }
161	    @media (hover: hover) and (prefers-reduced-motion: no-preference) {
162	      button:hover:not(:active) svg {
163	        transform: scale(1.05);
164	      }
165	    }
166	    .visually-hidden {
167	      position: absolute;
168	      width: 1px;
169	      height: 1px;
170	      overflow: hidden;
171	      clip-path: inset(50%);
172	      white-space: nowrap;
173	    }
174	    .status {
175	      margin-top: 2rem;
176	      font-weight: 600;
177	    }
178	    .hint {
179	      margin-top: 0.25rem;
180	      font-size: 0.875rem;
181	      opacity: 0.8;
182	    }
183	    @media (hover: none) and (pointer: coarse) {
184	      .hint .keys {
185	        display: none;
186	      }
187	    }
188	    kbd {
189	      display: inline-block;
190	      padding: 0.125rem 0.375rem;
191	      background: var(--kbd-bg);
192	      border: 1px solid transparent;
193	      border-radius: 0.25rem;
194	      font-family: monospace;
195	      font-size: 0.75em;
196	    }
197	  </style>
198	</head>
199	<body>
200	  <main>
201	    <h1 class="visually-hidden">Animated Circle</h1>
202	    <button type="button" class="no-transition" aria-label="Change circle color" aria-describedby="status hint">
203	      <svg viewBox="0 0 100 100" aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg">
204	        <circle cx="50" cy="50" r="50" fill="currentColor"/>
205	      </svg>
206	      <span class="color-indicator" aria-hidden="true"></span>
207	    </button>
208	    <p class="status" id="status" role="status" aria-atomic="true" aria-live="polite">Blue</p>
209	    <p class="hint" id="hint"><span class="verb">Click</span> to cycle<span class="keys"> • <kbd>Shift</kbd> reverse • <kbd>↑↓←→</kbd> navigate • <kbd>Home</kbd>/<kbd>End</kbd> jump</span></p>
210	  </main>
211	  <script>
212	    const button = document.querySelector('button');
213	    const status = document.querySelector('.status');
214	    const colors = ['blue', 'red', 'green', 'amber', 'violet', 'cyan'];
215	    const storageKey = 'circle-color';
216	
217	    // Safely retrieve saved color from localStorage, returning null if unavailable
218	    function loadColor() {
219	      try {
220	        return localStorage.getItem(storageKey);
221	      } catch {
222	        return null;
223	      }
224	    }
225	
226	    // Safely save color to localStorage, silently failing if unavailable
227	    function saveColor(color) {
228	      try {
229	        localStorage.setItem(storageKey, color);
230	      } catch {}
231	    }
232	
233	    const savedColor = loadColor();
234	    let index = colors.includes(savedColor) ? colors.indexOf(savedColor) : 0;
235	
236	    // Apply current color to button and update status display
237	    function applyColor() {
238	      const color = colors[index];
239	      if (color === 'blue') {
240	        delete button.dataset.color;
241	      } else {
242	        button.dataset.color = color;
243	      }
244	      status.textContent = color[0].toUpperCase() + color.slice(1);
245	    }
246	
247	    // Cycle color by step amount and trigger pulse animation
248	    function changeColor(step) {
249	      const next = (index + step + colors.length) % colors.length;
250	      // Home/End at the boundary shouldn't pulse or rewrite storage
251	      if (next === index) return;
252	      index = next;
253	      applyColor();
254	      saveColor(colors[index]);
255	
256	      // Haptic feedback for supported devices
257	      if (navigator.vibrate) navigator.vibrate(50);
258	
259	      button.classList.remove('color-changed');
260	      void button.offsetWidth;
261	      button.classList.add('color-changed');
262	    }
263	
264	    applyColor();
265	    // Double rAF ensures paint completes before enabling animations
266	    requestAnimationFrame(() => requestAnimationFrame(() => {
267	      button.classList.remove('no-transition');
268	    }));
269	
270	    // Update instructions to show "Tap" on touch devices or "Click" on hover-capable devices
271	    const hoverQuery = matchMedia('(hover: none)');
272	    const verbSpan = document.querySelector('.hint .verb');
273	    function updateVerb() {
274	      verbSpan.textContent = hoverQuery.matches ? 'Tap' : 'Click';
275	    }
276	    updateVerb();
277	    hoverQuery.addEventListener('change', updateVerb);
278	
279	    // Space and Enter activate through the native click, but keyboard-synthesized
280	    // clicks don't reliably carry shiftKey, so remember it from the key events
281	    let shiftHeld = false;
282	    const isActivationKey = (event) => event.key === 'Enter' || event.key === ' ';
283	    // Space clicks on keyup; Enter already clicked on keydown, so updating
284	    // shiftHeld on Enter's keyup would leak into the next mouse click
285	    button.addEventListener('keyup', (event) => {
286	      if (event.key === ' ') shiftHeld = event.shiftKey;
287	    });
288	    button.addEventListener('blur', () => {
289	      shiftHeld = false;
290	    });
291	
292	    const keySteps = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 };
293	    button.addEventListener('keydown', (event) => {
294	      if (isActivationKey(event)) {
295	        // Holding Enter would otherwise fire a click on every repeat; no click
296	        // follows to reset shiftHeld, so setting it here would leak into the
297	        // next mouse click
298	        if (event.repeat) {
299	          if (event.key === 'Enter') event.preventDefault();
300	          return;
301	        }
302	        shiftHeld = event.shiftKey;
303	        return;
304	      }
305	      if (event.altKey || event.ctrlKey || event.metaKey) return;
306	      if (event.key in keySteps) {
307	        event.preventDefault();
308	        changeColor(keySteps[event.key]);
309	      } else if (event.key === 'Home') {
310	        event.preventDefault();
311	        changeColor(-index);
312	      } else if (event.key === 'End') {
313	        event.preventDefault();
314	        changeColor(colors.length - 1 - index);
315	      }
316	    });
317	    button.addEventListener('click', (event) => {
318	      changeColor(event.shiftKey || shiftHeld ? -1 : 1);
319	      shiftHeld = false;
320	    });
321	    button.addEventListener('animationend', () => {
322	      button.classList.remove('color-changed');
323	    });
324	    // Sync color across tabs when storage changes
325	    addEventListener('storage', (event) => {
326	      // key is null when another tab calls localStorage.clear()
327	      if (event.key !== storageKey && event.key !== null) return;
328	      const newIndex = colors.indexOf(event.newValue);
329	      index = newIndex === -1 ? 0 : newIndex;
330	      applyColor();
331	    });
332	  </script>
333	</body>
334	</html>
